import 'package:cephalopod/features/settings/presentation/models/theme_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'settings_view_state.freezed.dart';

/// Everything the settings page shows: the [theme] chosen, which the app
/// follows too, and whether the game board marks the last move
/// ([highlightLastMove]).
///
/// A UI model (docs/adr/0015): plain data generated by freezed
/// (docs/adr/0011).
@freezed
abstract class SettingsViewState with _$SettingsViewState {
  const factory SettingsViewState({
    required ThemeUi theme,
    required bool highlightLastMove,
  }) = _SettingsViewState;
}
